     * @return int table offset
     */
    public static function endGCT(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        $builder->required($o, 4);  // FIELD_ID
        $builder->required($o, 46);  // AMPLITUDE_UNITS
        return $o;
    }

